+    data[1] = (char)0xCD; // PT=205(RTPFB)
+    data[2] = (char)0x01; // length=501, (501+1)*4=2008 bytes
+    data[3] = (char)0xF5;
+    SrsBuffer buffer(data, sizeof(data));
+    SrsRtcpCompound compound;
+    srs_error_t err = compound.decode(&buffer);
+    EXPECT_TRUE(err != srs_success);
+    srs_freep(err);
+}
